-- 0034: fill الأربعين الإيمانية from صحيح البخاري، كتاب الإيمان.
--
-- The collection was created empty in 0025 pending a decision on
-- محمد بن شمس الدين's compilation — a modern work whose *selection* of forty is
-- copyrighted even though the hadith themselves are not. The owner chose to
-- build a collection from public-domain sources instead (2026-08-01).
--
-- ## What this is, and what it is not
-- These are the **first forty hadith of كتاب الإيمان in صحيح البخاري**, in
-- Bukhari's own order, taken verbatim from the Sultaniyya edition on turath.io
-- (book 1681) — the same source pipeline as بلوغ المرام.
--
-- It is NOT ابن شمس الدين's الأربعين الإيمانية and must not be presented as
-- such; the description below names its actual source. "First forty in the
-- source's own order" is deliberately a mechanical rule rather than a curated
-- pick: Kitab al-Iman holds 51 hadith (8–58), and any *selection* of forty from
-- them would be an editorial judgement on creed that belongs to a scholar, not
-- to this migration.
--
-- Isnad is kept verbatim. Trimming "حدثنا فلان عن فلان" to shorten the matn for
-- a phone screen would be editing hadith text, which no display convenience
-- justifies.
--
-- Grading is 'أخرجه البخاري' on every entry — a statement of fact about where
-- the text comes from, not a judgement added on top of it.
--
-- Idempotent: re-running replaces the same rows.

update content.hadith_collections
set description_translations = jsonb_build_object(
      'ar', 'أربعون حديثاً في الإيمان من كتاب الإيمان في صحيح البخاري',
      'en', 'Forty hadith on faith, from the Book of Faith in Sahih al-Bukhari'
    ),
    version = version + 1
where slug = 'arbaeen_imaniyya';

insert into content.hadith_entries
  (collection_id, number, arabic_text, translation_translations, grading,
   benefit_note_translations, source, source_dataset, review_status,
   reviewed_by, reviewed_at, published, version)
select c.id, v.number, v.matn, '{}'::jsonb, v.grading, '{}'::jsonb, v.source,
       'Shamela/turath.io #1681 — صحيح البخاري، كتاب الإيمان (Arabic matn only)',
       'approved', 'owner:public-domain-source', now(), true, 1
from (values
  (1, 'حَدَّثَنَا عُبَيْدُ اللهِ بْنُ مُوسَى قَالَ: أَخْبَرَنَا حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ، عَنْ عِكْرِمَةَ بْنِ خَالِدٍ، عَنِ ابْنِ عُمَرَ ﵄ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ».  بَابُ أُمُورِ الْإِيمَانِ وَقَوْلِ اللهِ تَعَالَى ﴿لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَكِنَّ الْبِرَّ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الآخِرِ وَالْمَلائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ وَآتَى الْمَالَ عَلَى حُبِّهِ ذَوِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقَابِ وَأَقَامَ الصَّلاةَ وَآتَى الزَّكَاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ أُولَئِكَ الَّذِينَ صَدَقُوا وَأُولَئِكَ هُمُ الْمُتَّقُونَ﴾ ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾ الْآيَةَ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 8'),
  (2, 'حَدَّثَنَا عَبْدُ اللهِ بْنُ مُحَمَّدٍ ، قَالَ: حَدَّثَنَا أَبُو عَامِرٍ الْعَقَدِيُّ ، قَالَ: حَدَّثَنَا سُلَيْمَانُ بْنُ بِلَالٍ، عَنْ عَبْدِ اللهِ بْنِ دِينَارٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ﵁، عَنِ النَّبِيِّ ﷺ قَالَ: «الْإِيمَانُ بِضْعٌ وَسِتُّونَ شُعْبَةً، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ».  بَابٌ: الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 9'),
  (3, 'حَدَّثَنَا آدَمُ بْنُ أَبِي إِيَاسٍ ، قَالَ: حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ اللهِ بْنِ أَبِي السَّفَرِ وَإِسْمَاعِيلَ ، عَنِ الشَّعْبِيِّ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو ﵄، عَنِ النَّبِيِّ ﷺ، قَالَ: «الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللهُ عَنْهُ» قَالَ أَبُو عَبْدِ اللهِ: وَقَالَ أَبُو مُعَاوِيَةَ: حَدَّثَنَا دَاوُدُ عَنْ عَامِرٍ قَالَ: سَمِعْتُ عَبْدَ اللهِ، عَنِ النَّبِيِّ ﷺ. وَقَالَ عَبْدُ الْأَعْلَى: عَنْ دَاوُدَ عَنْ عَامِرٍ عَنْ عَبْدِ اللهِ عَنِ النَّبِيِّ ﷺ.  بَابٌ: أَيُّ الْإِسْلَامِ أَفْضَلُ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 10'),
  (4, 'حَدَّثَنَا سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقُرَشِيِّ  ⦗١٢⦘ قَالَ: حَدَّثَنَا أَبِي قَالَ: حَدَّثَنَا أَبُو بُرْدَةَ بْنُ عَبْدِ اللهِ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى ﵁ قَالَ: «قَالُوا: يَا رَسُولَ اللهِ، أَيُّ الْإِسْلَامِ أَفْضَلُ؟ قَالَ: مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ».  بَابٌ: إِطْعَامُ الطَّعَامِ مِنَ الْإِسْلَامِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 11'),
  (5, 'حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ قَالَ: حَدَّثَنَا اللَّيْثُ، عَنْ يَزِيدَ، عَنْ أَبِي الْخَيْرِ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو ﵄: «أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ﷺ: أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ».  بَابٌ: مِنَ الْإِيمَانِ أَنْ يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 12'),
  (6, 'حَدَّثَنَا مُسَدَّدٌ قَالَ: حَدَّثَنَا يَحْيَى، عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ﵁، عَنِ النَّبِيِّ ﷺ. وَعَنْ حُسَيْنٍ الْمُعَلِّمِ قَالَ: حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ».  بَابٌ: حُبُّ الرَّسُولِ ﷺ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 13'),
  (7, 'حَدَّثَنَا أَبُو الْيَمَانِ قَالَ: أَخْبَرَنَا شُعَيْبٌ قَالَ: حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الْأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ﵁: أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «فَوَالَّذِي نَفْسِي بِيَدِهِ لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ».', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 14'),
  (8, 'حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ قَالَ: حَدَّثَنَا ابْنُ عُلَيَّةَ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ ﷺ (ح). وَحَدَّثَنَا آدَمُ قَالَ: حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ قَالَ: قَالَ النَّبِيُّ ﷺ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ».  بَابُ حَلَاوَةِ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 15'),
  (9, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى قَالَ: حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ قَالَ: حَدَّثَنَا أَيُّوبُ، عَنْ أَبِي قِلَابَةَ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ ﷺ قَالَ: «ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ: أَنْ يَكُونَ اللهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلهِ، وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ».  بَابٌ: عَلَامَةُ الْإِيمَانِ حُبُّ الْأَنْصَارِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 16'),
  (10, 'حَدَّثَنَا أَبُو الْوَلِيدِ قَالَ: حَدَّثَنَا شُعْبَةُ قَالَ: أَخْبَرَنِي عَبْدُ اللهِ بْنُ عَبْدِ اللهِ بْنِ جَبْرٍ قَالَ: سَمِعْتُ أَنَسًا، عَنِ النَّبِيِّ ﷺ قَالَ: «آيَةُ الْإِيمَانِ حُبُّ الْأَنْصَارِ، وَآيَةُ النِّفَاقِ بُغْضُ الْأَنْصَارِ.»  بَابٌ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 17'),
  (11, 'حَدَّثَنَا أَبُو الْيَمَانِ قَالَ: أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ قَالَ: أَخْبَرَنِي أَبُو إِدْرِيسَ عَائِذُ اللهِ بْنُ عَبْدِ اللهِ: أَنَّ عُبَادَةَ بْنَ الصَّامِتِ ﵁، وَكَانَ شَهِدَ بَدْرًا، وَهُوَ أَحَدُ النُّقَبَاءِ لَيْلَةَ الْعَقَبَةِ: «أَنَّ رَسُولَ اللهِ ﷺ قَالَ، وَحَوْلَهُ عِصَابَةٌ مِنْ أَصْحَابِهِ: بَايِعُونِي عَلَى أَلَّا تُشْرِكُوا بِاللهِ شَيْئًا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا، وَلَا تَقْتُلُوا أَوْلَادَكُمْ، ⦗١٣⦘ وَلَا تَأْتُوا بِبُهْتَانٍ تَفْتَرُونَهُ بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ، وَلَا تَعْصُوا فِي مَعْرُوفٍ، فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللهِ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ فِي الدُّنْيَا فَهُوَ كَفَّارَةٌ لَهُ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللهُ فَهُوَ إِلَى اللهِ، إِنْ شَاءَ عَفَا عَنْهُ وَإِنْ شَاءَ عَاقَبَهُ. فَبَايَعْنَاهُ عَلَى ذَلِكَ».  بَابٌ: مِنَ الدِّينِ الْفِرَارُ مِنَ الْفِتَنِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 18'),
  (12, 'حَدَّثَنَا عَبْدُ اللهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا شَعَفَ الْجِبَالِ وَمَوَاقِعَ الْقَطْرِ، يَفِرُّ بِدِينِهِ مِنَ الْفِتَنِ».  بَابُ قَوْلُِ النَّبِيِّ ﷺ أَنَا أَعْلَمُكُمْ بِاللهِ وَأَنَّ الْمَعْرِفَةَ فِعْلُ الْقَلْبِ لِقَوْلِ اللهِ تَعَالَى ﴿وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 19'),
  (13, 'حَدَّثَنَا مُحَمَّدُ بْنُ سَلَامٍ قَالَ: أَخْبَرَنَا عَبْدَةُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ قَالَتْ: «كَانَ رَسُولُ اللهِ ﷺ إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنَ الْأَعْمَالِ بِمَا يُطِيقُونَ، قَالُوا: إِنَّا لَسْنَا كَهَيْئَتِكَ يَا رَسُولَ اللهِ، إِنَّ اللهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، فَيَغْضَبُ حَتَّى يُعْرَفَ الْغَضَبُ فِي وَجْهِهِ، ثُمَّ يَقُولُ: إِنَّ أَتْقَاكُمْ وَأَعْلَمَكُمْ بِاللهِ أَنَا».  بَابٌ: مَنْ كَرِهَ أَنْ يَعُودَ فِي الْكُفْرِ كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 20'),
  (14, 'حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ قَالَ: حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ﵁، عَنِ النَّبِيِّ ﷺ قَالَ: «ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ: مَنْ كَانَ اللهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ أَحَبَّ عَبْدًا لَا يُحِبُّهُ إِلَّا لِلهِ، وَمَنْ يَكْرَهُ أَنْ يَعُودَ فِي الْكُفْرِ - بَعْدَ إِذْ أَنْقَذَهُ اللهُ - كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ».  بَابُ تَفَاضُلِ أَهْلِ الْإِيمَانِ فِي الْأَعْمَالِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 21'),
  (15, 'حَدَّثَنَا إِسْمَاعِيلُ قَالَ: حَدَّثَنِي مَالِكٌ، عَنْ عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ﵁، عَنِ النَّبِيِّ ﷺ قَالَ: «يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ، وَأَهْلُ النَّارِ النَّارَ، ثُمَّ يَقُولُ اللهُ تَعَالَى: أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ. فَيُخْرَجُونَ مِنْهَا قَدِ اسْوَدُّوا، فَيُلْقَوْنَ فِي نَهَرِ الْحَيَا أَوِ الْحَيَاةِ - شَكَّ مَالِكٌ - فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي جَانِبِ السَّيْلِ، أَلَمْ تَرَ أَنَّهَا تَخْرُجُ صَفْرَاءَ مُلْتَوِيَةً» قَالَ وُهَيْبٌ: حَدَّثَنَا عَمْرٌو: الْحَيَاةِ، وَقَالَ: خَرْدَلٍ مِنْ خَيْرٍ.', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 22'),
  (16, 'حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدِ اللهِ قَالَ: حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ: أَنَّهُ سَمِعَ أَبَا سَعِيدٍ الْخُدْرِيَّ يَقُولُ: قَالَ رَسُولُ اللهِ ﷺ: «بَيْنَا أَنَا نَائِمٌ، رَأَيْتُ النَّاسَ يُعْرَضُونَ عَلَيَّ وَعَلَيْهِمْ قُمُصٌ، مِنْهَا مَا يَبْلُغُ الثُّدِيَّ، وَمِنْهَا مَا دُونَ ذَلِكَ، وَعُرِضَ ⦗١٤⦘ عَلَيَّ عُمَرُ بْنُ الْخَطَّابِ وَعَلَيْهِ قَمِيصٌ يَجُرُّهُ. قَالُوا: فَمَا أَوَّلْتَ ذَلِكَ يَا رَسُولَ اللهِ؟ قَالَ: الدِّينَ».  بَابٌ: الْحَيَاءُ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 23'),
  (17, 'حَدَّثَنَا عَبْدُ اللهِ بْنُ يُوسُفَ قَالَ: أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمِ بْنِ عَبْدِ اللهِ، عَنْ أَبِيهِ : «أَنَّ رَسُولَ اللهِ ﷺ مَرَّ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ وَهُوَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ، فَقَالَ رَسُولُ اللهِ ﷺ: دَعْهُ فَإِنَّ الْحَيَاءَ مِنَ الْإِيمَانِ».  بَابٌ: ﴿فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 24'),
  (18, 'حَدَّثَنَا عَبْدُ اللهِ بْنُ مُحَمَّدٍ الْمُسْنَدِيُّ قَالَ: حَدَّثَنَا أَبُو رَوْحٍ الْحَرَمِيُّ بْنُ عُمَارَةَ قَالَ: حَدَّثَنَا شُعْبَةُ، عَنْ وَاقِدِ بْنِ مُحَمَّدٍ قَالَ: سَمِعْتُ أَبِي يُحَدِّثُ عَنِ ابْنِ عُمَرَ : أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللهِ».  بَابُ مَنْ قَالَ إِنَّ الْإِيمَانَ هُوَ الْعَمَلُ لِقَوْلِ اللهِ تَعَالَى ﴿وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ﴾ وَقَالَ عِدَّةٌ مِنْ أَهْلِ الْعِلْمِ فِي قَوْلِهِ تَعَالَى ﴿فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ * عَمَّا كَانُوا يَعْمَلُونَ﴾ عَنْ قَوْلِ لَا إِلَهَ إِلَّا اللهُ ﴿لِمِثْلِ هَذَا فَلْيَعْمَلِ الْعَامِلُونَ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 25'),
  (19, 'حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، وَمُوسَى بْنُ إِسْمَاعِيلَ قَالَا: حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ قَالَ: حَدَّثَنَا ابْنُ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ : «أَنَّ رَسُولَ اللهِ ﷺ سُئِلَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ فَقَالَ: إِيمَانٌ بِاللهِ وَرَسُولِهِ. قِيلَ: ثُمَّ مَاذَا؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللهِ. قِيلَ: ثُمَّ مَاذَا؟ قَالَ: حَجٌّ مَبْرُورٌ».  بَابٌ: إِذَا لَمْ يَكُنِ الْإِسْلَامُ عَلَى الْحَقِيقَةِ وَكَانَ عَلَى الِاسْتِسْلَامِ أَوِ الْخَوْفِ مِنَ الْقَتْلِ لِقَوْلِهِ تَعَالَى ﴿قَالَتِ الأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾ فَإِذَا كَانَ عَلَى الْحَقِيقَةِ فَهُوَ عَلَى قَوْلِهِ جَلَّ ذِكْرُهُ ﴿إِنَّ الدِّينَ عِنْدَ اللهِ الإِسْلامُ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 26'),
  (20, 'حَدَّثَنَا أَبُو الْيَمَانِ قَالَ: أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ قَالَ: أَخْبَرَنِي عَامِرُ بْنُ سَعْدِ بْنِ أَبِي وَقَّاصٍ، عَنْ سَعْدٍ ﵁: «أَنَّ رَسُولَ اللهِ ﷺ أَعْطَى رَهْطًا وَسَعْدٌ جَالِسٌ، فَتَرَكَ رَسُولُ اللهِ ﷺ رَجُلًا هُوَ أَعْجَبُهُمْ إِلَيَّ، فَقُلْتُ: يَا رَسُولَ اللهِ، مَا لَكَ عَنْ فُلَانٍ؟ فَوَاللهِ إِنِّي لَأَرَاهُ مُؤْمِنًا، فَقَالَ: أَوْ مُسْلِمًا. فَسَكَتُّ قَلِيلًا، ثُمَّ غَلَبَنِي مَا أَعْلَمُ مِنْهُ، فَعُدْتُ لِمَقَالَتِي فَقُلْتُ: مَا لَكَ عَنْ فُلَانٍ؟ فَوَاللهِ إِنِّي لَأَرَاهُ مُؤْمِنًا، فَقَالَ: أَوْ مُسْلِمًا. ثُمَّ غَلَبَنِي مَا أَعْلَمُ مِنْهُ فَعُدْتُ لِمَقَالَتِي، وَعَادَ رَسُولُ اللهِ ﷺ، ثُمَّ قَالَ: يَا سَعْدُ إِنِّي لَأُعْطِي الرَّجُلَ، وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ، خَشْيَةَ أَنْ يَكُبَّهُ اللهُ فِي النَّارِ.» وَرَوَاهُ يُونُسُ، وَصَالِحٌ، وَمَعْمَرٌ، وَابْنُ أَخِي الزُّهْرِيِّ، عَنِ الزُّهْرِيِّ.  بَابٌ: إِفْشَاءُ السَّلَامِ مِنَ الْإِسْلَامِ وَقَالَ عَمَّارٌ ثَلَاثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلَامِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الْإِقْتَارِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 27'),
  (21, 'حَدَّثَنَا قُتَيْبَةُ قَالَ: حَدَّثَنَا اللَّيْثُ، عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ، عَنْ أَبِي الْخَيْرِ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو : «أَنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ ﷺ: أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ».  بَابُ كُفْرَانِ الْعَشِيرِ وَكُفْرٍ بَعْدَ كُفْرٍ. فِيهِ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ ﷺ.', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 28'),
  (22, 'حَدَّثَنَا عَبْدُ اللهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ النَّبِيُّ ﷺ: «أُرِيتُ النَّارَ فَإِذَا أَكْثَرُ أَهْلِهَا النِّسَاءُ، يَكْفُرْنَ. قِيلَ: أَيَكْفُرْنَ بِاللهِ؟ قَالَ: يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الْإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ ثُمَّ رَأَتْ مِنْكَ شَيْئًا، قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ».  بَابٌ: الْمَعَاصِي مِنْ أَمْرِ الْجَاهِلِيَّةِ وَلَا يُكَفَّرُ صَاحِبُهَا بِارْتِكَابِهَا إِلَّا بِالشِّرْكِ لِقَوْلِ النَّبِيِّ ﷺ إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ وَقَوْلِ اللهِ تَعَالَى ﴿إِنَّ اللهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 29'),
  (23, 'حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ قَالَ: حَدَّثَنَا شُعْبَةُ، عَنْ وَاصِلٍ الْأَحْدَبِ، عَنِ الْمَعْرُورِ قَالَ: «لَقِيتُ أَبَا ذَرٍّ بِالرَّبَذَةِ وَعَلَيْهِ حُلَّةٌ، وَعَلَى غُلَامِهِ حُلَّةٌ، فَسَأَلْتُهُ عَنْ ذَلِكَ، فَقَالَ: إِنِّي سَابَبْتُ رَجُلًا فَعَيَّرْتُهُ بِأُمِّهِ، فَقَالَ لِيَ النَّبِيُّ ﷺ: يَا أَبَا ذَرٍّ أَعَيَّرْتَهُ بِأُمِّهِ؟ إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ، إِخْوَانُكُمْ خَوَلُكُمْ، جَعَلَهُمُ اللهُ تَحْتَ أَيْدِيكُمْ، فَمَنْ كَانَ أَخُوهُ تَحْتَ يَدِهِ فَلْيُطْعِمْهُ مِمَّا يَأْكُلُ، وَلْيُلْبِسْهُ مِمَّا يَلْبَسُ، وَلَا تُكَلِّفُوهُمْ مَا يَغْلِبُهُمْ، فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ».  بَابٌ: ﴿وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا﴾ فَسَمَّاهُمُ الْمُؤْمِنِينَ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 30'),
  (24, 'حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ الْمُبَارَكِ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، حَدَّثَنَا أَيُّوبُ، وَيُونُسُ، عَنِ الْحَسَنِ، عَنِ الْأَحْنَفِ بْنِ قَيْسٍ قَالَ: «ذَهَبْتُ لِأَنْصُرَ هَذَا الرَّجُلَ، فَلَقِيَنِي أَبُو بَكْرَةَ فَقَالَ: أَيْنَ تُرِيدُ؟ قُلْتُ: أَنْصُرُ هَذَا الرَّجُلَ. قَالَ: ارْجِعْ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا، فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ. فَقُلْتُ: يَا رَسُولَ اللهِ، هَذَا الْقَاتِلُ، فَمَا بَالُ الْمَقْتُولِ؟ قَالَ: إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ».  بَابٌ: ظُلْمٌ دُونَ ظُلْمٍ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 31'),
  (25, 'حَدَّثَنَا أَبُو الْوَلِيدِ قَالَ: حَدَّثَنَا شُعْبَةُ، (ح) قَالَ: وَحَدَّثَنِي بِشْرٌ قَالَ: حَدَّثَنَا مُحَمَّدٌ ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللهِ قَالَ: «لَمَّا نَزَلَتْ: ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ﴾ قَالَ أَصْحَابُ رَسُولِ اللهِ ﷺ: أَيُّنَا لَمْ يَظْلِمْ؟ فَأَنْزَلَ اللهُ: ﴿إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾» .  بَابُ عَلَامَةِ الْمُنَافِقِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 32'),
  (26, 'حَدَّثَنَا سُلَيْمَانُ أَبُو الرَّبِيعِ قَالَ: حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ قَالَ: حَدَّثَنَا نَافِعُ بْنُ مَالِكِ بْنِ أَبِي عَامِرٍ أَبُو سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ ﷺ قَالَ: «آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ».', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 33'),
  (27, 'حَدَّثَنَا قَبِيصَةُ بْنُ عُقْبَةَ قَالَ: حَدَّثَنَا سُفْيَانُ، عَنِ الْأَعْمَشِ، عَنْ عَبْدِ اللهِ بْنِ مُرَّةَ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو، أَنَّ النَّبِيَّ ﷺ قَالَ: «أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا خَالِصًا، وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ، كَانَتْ فِيهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا: إِذَا اؤْتُمِنَ خَانَ، وَإِذَا حَدَّثَ كَذَبَ، وَإِذَا عَاهَدَ غَدَرَ، وَإِذَا خَاصَمَ فَجَرَ.» تَابَعَهُ شُعْبَةُ، عَنِ الْأَعْمَشِ.  بَابٌ: قِيَامُ لَيْلَةِ الْقَدْرِ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 34'),
  (28, 'حَدَّثَنَا أَبُو الْيَمَانِ قَالَ: أَخْبَرَنَا شُعَيْبٌ قَالَ: حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الْأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».  بَابٌ: الْجِهَادُ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 35'),
  (29, 'حَدَّثَنَا حَرَمِيُّ بْنُ حَفْصٍ قَالَ: حَدَّثَنَا عَبْدُ الْوَاحِدِ قَالَ: حَدَّثَنَا عُمَارَةُ قَالَ: حَدَّثَنَا أَبُو زُرْعَةَ بْنُ عَمْرِو بْنِ جَرِيرٍ قَالَ: سَمِعْتُ أَبَا هُرَيْرَةَ، عَنِ النَّبِيِّ ﷺ قَالَ: «انْتَدَبَ اللهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ، لَا يُخْرِجُهُ إِلَّا إِيمَانٌ بِي وَتَصْدِيقٌ بِرُسُلِي، أَنْ أَرْجِعَهُ بِمَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ، أَوْ أُدْخِلَهُ الْجَنَّةَ، وَلَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ، وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللهِ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلُ».  بَابٌ: تَطَوُّعُ قِيَامِ رَمَضَانَ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 36'),
  (30, 'حَدَّثَنَا إِسْمَاعِيلُ قَالَ: حَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي هُرَيْرَةَ : أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».  بَابٌ: صَوْمُ رَمَضَانَ احْتِسَابًا مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 37'),
  (31, 'حَدَّثَنَا ابْنُ سَلَامٍ قَالَ: أَخْبَرَنَا مُحَمَّدُ بْنُ فُضَيْلٍ قَالَ: حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ «مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».  بَابٌ: الدِّينُ يُسْرٌ وَقَوْلُ النَّبِيِّ ﷺ: أَحَبُّ الدِّينِ إِلَى اللهِ الْحَنِيفِيَّةُ السَّمْحَةُ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 38'),
  (32, 'حَدَّثَنَا عَبْدُ السَّلَامِ بْنُ مُطَهَّرٍ قَالَ: حَدَّثَنَا عُمَرُ بْنُ عَلِيٍّ، عَنْ مَعْنِ بْنِ مُحَمَّدٍ الْغِفَارِيِّ، عَنْ سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا، وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ، وَشَيْءٍ مِنَ الدُّلْجَةِ».  بَابٌ: الصَّلَاةُ مِنَ الْإِيمَانِ وَقَوْلُ اللهِ تَعَالَى: ﴿وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ﴾ يَعْنِي صَلَاتَكُمْ عِنْدَ الْبَيْتِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 39'),
  (33, 'حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ قَالَ: حَدَّثَنَا زُهَيْرٌ قَالَ: حَدَّثَنَا أَبُو إِسْحَاقَ، عَنِ الْبَرَاءِ : «أَنَّ النَّبِيَّ ﷺ كَانَ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ نَزَلَ عَلَى أَجْدَادِهِ، أَوْ قَالَ أَخْوَالِهِ مِنَ الْأَنْصَارِ، وَأَنَّهُ صَلَّى قِبَلَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا، أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَأَنَّهُ صَلَّى أَوَّلَ صَلَاةٍ صَلَّاهَا صَلَاةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ وَهُمْ رَاكِعُونَ، فَقَالَ: أَشْهَدُ بِاللهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللهِ ﷺ قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَتِ الْيَهُودُ قَدْ أَعْجَبَهُمْ إِذْ كَانَ يُصَلِّي قِبَلَ بَيْتِ الْمَقْدِسِ، وَأَهْلُ الْكِتَابِ، فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ الْبَيْتِ، أَنْكَرُوا ذَلِكَ. قَالَ زُهَيْرٌ: حَدَّثَنَا أَبُو إِسْحَاقَ، عَنِ الْبَرَاءِ فِي حَدِيثِهِ هَذَا: أَنَّهُ مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ رِجَالٌ وَقُتِلُوا، فَلَمْ نَدْرِ مَا نَقُولُ فِيهِمْ. فَأَنْزَلَ اللهُ تَعَالَى: ﴿وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ﴾».  بَابُ حُسْنُِ إِسْلَامِ الْمَرْءِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 40'),
  (34, 'قَالَ مَالِكٌ: أَخْبَرَنِي زَيْدُ بْنُ أَسْلَمَ، أَنَّ عَطَاءَ بْنَ يَسَارٍ أَخْبَرَهُ، أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ، أَنَّهُ سَمِعَ رَسُولَ اللهِ ﷺ يَقُولُ: إِذَا أَسْلَمَ الْعَبْدُ فَحَسُنَ إِسْلَامُهُ يُكَفِّرُ اللهُ عَنْهُ كُلَّ سَيِّئَةٍ كَانَ زَلَفَهَا، وَكَانَ بَعْدَ ذَلِكَ الْقِصَاصُ، الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَالسَّيِّئَةُ بِمِثْلِهَا إِلَّا أَنْ يَتَجَاوَزَ اللهُ عَنْهَا.', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 41'),
  (35, 'حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ قَالَ: حَدَّثَنَا عَبْدُ الرَّزَّاقِ قَالَ: أَخْبَرَنَا مَعْمَرٌ، عَنْ هَمَّامٍ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلَامَهُ، فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِمِثْلِهَا».  بَابٌ: أَحَبُّ الدِّينِ إِلَى اللهِ أَدْوَمُهُ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 42'),
  (36, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، عَنْ هِشَامٍ قَالَ: أَخْبَرَنِي أَبِي، عَنْ عَائِشَةَ : «أَنَّ النَّبِيَّ ﷺ دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ، قَالَ: مَنْ هَذِهِ؟ قَالَتْ: فُلَانَةُ، تَذْكُرُ مِنْ صَلَاتِهَا. قَالَ: مَهْ، عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللهِ لَا يَمَلُّ اللهُ حَتَّى تَمَلُّوا، وَكَانَ أَحَبَّ الدِّينِ إِلَيْهِ مَا دَاوَمَ عَلَيْهِ صَاحِبُهُ».  بَابُ زِيَادَةِ الْإِيمَانِ وَنُقْصَانِهِ وَقَوْلِ اللهِ تَعَالَى ﴿وَزِدْنَاهُمْ هُدًى﴾ ﴿وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا﴾ وَقَالَ ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾ فَإِذَا تَرَكَ شَيْئًا مِنَ الْكَمَالِ فَهُوَ نَاقِصٌ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 43'),
  (37, 'حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ قَالَ: حَدَّثَنَا هِشَامٌ قَالَ: حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ ﷺ قَالَ: «يَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ ⦗١٨⦘ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ بُرَّةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ ذَرَّةٍ مِنْ خَيْرٍ.» قَالَ أَبُو عَبْدِ اللهِ: قَالَ أَبَانُ: حَدَّثَنَا قَتَادَةُ: حَدَّثَنَا أَنَسٌ، عَنِ النَّبِيِّ ﷺ: مِنْ إِيمَانٍ مَكَانَ مِنْ خَيْرٍ.', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 44'),
  (38, 'حَدَّثَنَا الْحَسَنُ بْنُ الصَّبَّاحِ، سَمِعَ جَعْفَرَ بْنَ عَوْنٍ، حَدَّثَنَا أَبُو الْعُمَيْسِ، أَخْبَرَنَا قَيْسُ بْنُ مُسْلِمٍ، عَنْ طَارِقِ بْنِ شِهَابٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ : «أَنَّ رَجُلًا مِنَ الْيَهُودِ قَالَ لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا، لَوْ عَلَيْنَا مَعْشَرَ الْيَهُودِ نَزَلَتْ لَاتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا. قَالَ: أَيُّ آيَةٍ؟ قَالَ: ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا﴾ قَالَ عُمَرُ: قَدْ عَرَفْنَا ذَلِكَ الْيَوْمَ وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ ﷺ، وَهُوَ قَائِمٌ بِعَرَفَةَ يَوْمَ جُمُعَةٍ».  بَابٌ: الزَّكَاةُ مِنَ الْإِسْلَامِ وَقَوْلُهُ ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 45'),
  (39, 'حَدَّثَنَا إِسْمَاعِيلُ قَالَ: حَدَّثَنِي مَالِكُ بْنُ أَنَسٍ، عَنْ عَمِّهِ أَبِي سُهَيْلِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ طَلْحَةَ بْنَ عُبَيْدِ اللهِ يَقُولُ: «جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ ﷺ مِنْ أَهْلِ نَجْدٍ ثَائِرُ الرَّأْسِ، يُسْمَعُ دَوِيُّ صَوْتِهِ وَلَا يُفْقَهُ مَا يَقُولُ، حَتَّى دَنَا، فَإِذَا هُوَ يَسْأَلُ عَنِ الْإِسْلَامِ، فَقَالَ رَسُولُ اللهِ ﷺ: خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ. فَقَالَ: هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ. قَالَ رَسُولُ اللهِ ﷺ: وَصِيَامُ رَمَضَانَ. قَالَ: هَلْ عَلَيَّ غَيْرُهُ؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ. قَالَ: وَذَكَرَ لَهُ رَسُولُ اللهِ ﷺ الزَّكَاةَ، قَالَ: هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ. قَالَ: فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ: وَاللهِ لَا أَزِيدُ عَلَى هَذَا وَلَا أَنْقُصُ. قَالَ رَسُولُ اللهِ ﷺ: أَفْلَحَ إِنْ صَدَقَ».  بَابٌ: اتِّبَاعُ الْجَنَائِزِ مِنَ الْإِيمَانِ', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 46'),
  (40, 'حَدَّثَنَا أَحْمَدُ بْنُ عَبْدِ اللهِ بْنِ عَلِيٍّ الْمَنْجُوفِيُّ قَالَ: حَدَّثَنَا رَوْحٌ قَالَ: حَدَّثَنَا عَوْفٌ، عَنِ الْحَسَنِ وَمُحَمَّدٍ، عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «مَنِ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا وَاحْتِسَابًا، وَكَانَ مَعَهُ حَتَّى يُصَلَّى عَلَيْهَا وَيَفْرُغَ مِنْ دَفْنِهَا، فَإِنَّهُ يَرْجِعُ مِنَ الْأَجْرِ بِقِيرَاطَيْنِ؛ كُلُّ قِيرَاطٍ مِثْلُ أُحُدٍ، وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ، فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ.» تَابَعَهُ عُثْمَانُ الْمُؤَذِّنُ قَالَ: حَدَّثَنَا عَوْفٌ، عَنْ مُحَمَّدٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ ﷺ نَحْوَهُ.  بَابُ خَوْفِ الْمُؤْمِنِ مِنْ أَنْ يَحْبَطَ عَمَلُهُ وَهُوَ لَا يَشْعُرُ وَقَالَ إِبْرَاهِيمُ التَّيْمِيُّ: مَا عَرَضْتُ قَوْلِي عَلَى عَمَلِي إِلَّا خَشِيتُ أَنْ أَكُونَ مُكَذَّبًا، وَقَالَ ابْنُ أَبِي مُلَيْكَةَ: أَدْرَكْتُ ثَلَاثِينَ مِنْ أَصْحَابِ النَّبِيِّ ﷺ كُلُّهُمْ يَخَافُ النِّفَاقَ عَلَى نَفْسِهِ مَا مِنْهُمْ أَحَدٌ يَقُولُ: إِنَّهُ عَلَى إِيمَانِ جِبْرِيلَ وَمِيكَائِيلَ. وَيُذْكَرُ ⦗١٩⦘ عَنِ الْحَسَنِ: مَا خَافَهُ إِلَّا مُؤْمِنٌ وَلَا أَمِنَهُ إِلَّا مُنَافِقٌ، وَمَا يُحْذَرُ مِنَ الْإِصْرَارِ عَلَى النِّفَاقِ وَالْعِصْيَانِ مِنْ غَيْرِ تَوْبَةٍ لِقَوْلِ اللهِ تَعَالَى ﴿وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ﴾', 'أَخْرَجَهُ البُخَارِيُّ.', 'المكتبة الشاملة / turath.io — صحيح البخاري، ط السلطانية (كتاب رقم 1681) — كتاب الإيمان، حديث 47')
) as v(number, matn, grading, source)
cross join content.hadith_collections c
where c.slug = 'arbaeen_imaniyya'
on conflict (app_id, collection_id, number) do update
set arabic_text = excluded.arabic_text,
    grading = excluded.grading,
    source = excluded.source,
    published = true,
    review_status = 'approved',
    version = content.hadith_entries.version + 1;
